import { describe, expect, it } from "vitest";
import { clamp } from "../index.js";

describe("clamp with a reversed interval", () => {
  const interval = {
    start: new Date(2021, 1, 3),
    end: new Date(2021, 1, 1),
  };

  it("returns the earlier endpoint for a date before the interval", () => {
    expect(clamp(new Date(2021, 1, 1 - 1), interval)).toEqual(
      new Date(2021, 1, 1),
    );
  });

  it("returns the date for a date inside the interval", () => {
    expect(clamp(new Date(2021, 1, 2), interval)).toEqual(
      new Date(2021, 1, 2),
    );
  });

  it("returns the later endpoint for a date after the interval", () => {
    expect(clamp(new Date(2021, 1, 4), interval)).toEqual(
      new Date(2021, 1, 3),
    );
  });
});

