import { describe, expect, it } from "vitest";
import { clamp } from "../index.js";

describe("clamp with reversed interval", () => {
  const interval = {
    start: new Date(2021, 3, 1),
    end: new Date(2021, 2, 1),
  };

  it("returns the later endpoint for a date before the interval", () => {
    expect(clamp(new Date(2021, 1, 1), interval)).toEqual(interval.end);
  });

  it("returns the date for a date inside the interval", () => {
    const date = new Date(2021, 2, 15);
    expect(clamp(date, interval)).toEqual(date);
  });

  it("returns the earlier endpoint for a date after the interval", () => {
    expect(clamp(new Date(2021, 4, 1), interval)).toEqual(interval.start);
  });
});

