import { describe, expect, it } from "vitest";
import { clamp } from "../index.js";

describe("clamp with reversed interval", () => {
  const interval = {
    start: new Date(2003, 1, 1),
    end: new Date(2001, 1, 1),
  };

  it("returns the earlier endpoint for a date before the interval", () => {
    const result = clamp(new Date(2000, 1, 1), interval);
    expect(result).toEqual(new Date(2001, 1, 1));
  });

  it("returns the date for a date inside the interval", () => {
    const result = clamp(new Date(2002, 1, 1), interval);
    expect(result).toEqual(new Date(2002, 1, 1));
  });

  it("returns the later endpoint for a date after the interval", () => {
    const result = clamp(new Date(2004, 1, 1), interval);
    expect(result).toEqual(new Date(2003, 1, 1));
  });
});

