import { describe, expect, it } from "vitest";
import { clamp } from "../index.js";

describe("clamp with a reversed interval", () => {
  const interval = {
    start: new Date(2020, 0, 10),
    end: new Date(2020, 0, 1),
  };

  it("returns the earlier endpoint for dates before the interval", () => {
    const result = clamp(new Date(2019, 11, 31), interval);

    expect(result).toEqual(new Date(2020, 0, 1));
  });

  it("returns the date for dates inside the interval", () => {
    const result = clamp(new Date(2020, 0, 5), interval);

    expect(result).toEqual(new Date(2020, 0, 5));
  });

  it("returns the later endpoint for dates after the interval", () => {
    const result = clamp(new Date(2020, 0, 11), interval);

    expect(result).toEqual(new Date(2020, 0, 10));
  });
});

